import json
import os
import tempfile

import pytest

from sprat_app.app import create_app, Store


@pytest.fixture()
def client(monkeypatch):
    fd, path = tempfile.mkstemp()
    os.close(fd)
    monkeypatch.setenv("SPRAT_DATA_PATH", path)
    app = create_app()
    app.config["TESTING"] = True
    with app.test_client() as client:
        yield client
    os.remove(path)


def create_user(client, name, role):
    r = client.post("/users", json={"name": name, "role": role})
    assert r.status_code == 201
    return r.get_json()


def test_item_lifecycle_and_access(client):
    analyst = create_user(client, "Ana", "analyst")
    pm = create_user(client, "Pat", "project_manager")
    guest = create_user(client, "Gus", "guest")

    r = client.post("/items", headers={"X-User-Id": analyst["id"]}, json={"title": "Login", "content": "Req", "reviewers": [pm["id"]]})
    assert r.status_code == 201
    item = r.get_json()

    assert client.get(f"/items/{item['id']}", headers={"X-User-Id": guest["id"]}).status_code == 200
    assert client.post(f"/items/{item['id']}/submit", headers={"X-User-Id": analyst["id"]}).status_code == 200
    assert client.post(f"/items/{item['id']}/review", headers={"X-User-Id": pm["id"]}, json={"status": "final", "note": "ok"}).status_code == 200


def test_sensitive_draft_limits_metadata(client):
    analyst = create_user(client, "Ana", "analyst")
    guest = create_user(client, "Gus", "guest")
    r = client.post("/items", headers={"X-User-Id": analyst["id"]}, json={"title": "Secret", "content": "Top", "sensitive": True})
    item = r.get_json()
    data = client.get(f"/items/{item['id']}", headers={"X-User-Id": guest["id"]}).get_json()
    assert "content" not in data


def test_import_marks_partial_analysis(client):
    analyst = create_user(client, "Ana", "analyst")
    r = client.post("/import", headers={"X-User-Id": analyst["id"]}, json={"items": [{"title": "Imported", "content": "x"}]})
    assert r.status_code == 201
    imported = r.get_json()["imported"][0]
    assert imported["partial_analysis"] is True
    assert imported["unresolved"] is True
EOF

